import{f as e,g as t,l as n,n as r,p as i,s as a}from"./index-BMjwpmLP.js";import{t as o}from"./navigate-BrrQ70PI.js";var s={name:`FrontendHtmlCssPage`,methods:{handleNav(e){o(e)}}},c={class:`htmlcss-page`,style:{"--color-accent":`#7c5cfc`}},l={class:`page`},u={class:`topbar`},d={class:`links`};function f(r,o,s,f,p,m){return t(),e(`div`,c,[n(`div`,l,[n(`div`,u,[o[2]||=n(`h1`,null,`🎨 HTML & CSS`,-1),n(`div`,d,[n(`a`,{href:`#`,onClick:o[0]||=a(e=>m.handleNav(`/frontend/hub`),[`prevent`])},`← Frontend`),n(`a`,{href:`#`,onClick:o[1]||=a(e=>m.handleNav(`/`),[`prevent`])},`Trang chủ`)])]),o[3]||=i(`<p class="desc" data-v-25cae97f>Từ semantic HTML đến CSS hiện đại: Flexbox, Grid, Animation, Custom Properties, BEM, và 25+ kỹ thuật thực tế.</p><div class="section" data-v-25cae97f><h2 data-v-25cae97f>📐 HTML5 Semantic</h2><p data-v-25cae97f>Các thẻ semantic giúp SEO, accessibility, và maintain code tốt hơn.</p><pre data-v-25cae97f><code data-v-25cae97f>&lt;header&gt; &lt;nav&gt; &lt;main&gt; &lt;section&gt; &lt;article&gt; &lt;aside&gt; &lt;footer&gt;</code></pre><div class="grid-2" data-v-25cae97f><div class="card" data-v-25cae97f><h4 data-v-25cae97f>&lt;header&gt;</h4><p data-v-25cae97f>Đầu trang, chứa logo, navigation, search bar</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>&lt;nav&gt;</h4><p data-v-25cae97f>Điều hướng chính, menu links</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>&lt;main&gt;</h4><p data-v-25cae97f>Nội dung chính, chỉ 1 lần/trang</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>&lt;article&gt;</h4><p data-v-25cae97f>Nội dung độc lập, có thể tái sử dụng</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>&lt;section&gt;</h4><p data-v-25cae97f>Nhóm nội dung theo chủ đề</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>&lt;aside&gt;</h4><p data-v-25cae97f>Nội dung liên quan, sidebar</p></div></div></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>📦 CSS Box Model &amp; Units</h2><pre data-v-25cae97f><code data-v-25cae97f>* { box-sizing: border-box; } /* content-box vs border-box */</code></pre><p data-v-25cae97f><strong data-v-25cae97f>Units:</strong> <code data-v-25cae97f>px</code> (cố định), <code data-v-25cae97f>rem</code> (dựa trên root font-size), <code data-v-25cae97f>em</code> (dựa trên parent), <code data-v-25cae97f>%</code>, <code data-v-25cae97f>vw/vh</code> (viewport), <code data-v-25cae97f>ch</code> (độ rộng chữ), <code data-v-25cae97f>fr</code> (fraction trong grid)</p></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>🧩 Flexbox</h2><p data-v-25cae97f>Bố cục 1 chiều — dùng cho navigation, card rows, center content.</p><pre data-v-25cae97f><code data-v-25cae97f>.container {
  display: flex;
  justify-content: center; /* flex-start | center | space-between | space-around */
  align-items: center;     /* stretch | center | flex-start */
  gap: 1rem;               /* khoảng cách giữa các item */
  flex-wrap: wrap;         /* xuống dòng khi hết chỗ */
}
.item { flex: 1; }          /* chia đều không gian */</code></pre></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>🔲 CSS Grid</h2><p data-v-25cae97f>Bố cục 2 chiều — dùng cho layout chính, gallery, dashboard.</p><pre data-v-25cae97f><code data-v-25cae97f>.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);  /* 3 cột bằng nhau */
  grid-template-columns: 200px 1fr;        /* sidebar + content */
  gap: 1rem;
}
.item { grid-column: span 2; }            /* chiếm 2 cột */
.item { grid-area: 1 / 1 / 3 / 3; }       /* row-start / col-start / row-end / col-end */</code></pre></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>🎭 CSS Custom Properties (Variables)</h2><pre data-v-25cae97f><code data-v-25cae97f>:root {
  --primary: #6366f1;
  --radius: 8px;
  --shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.btn { background: var(--primary); border-radius: var(--radius); }
/* Fallback: var(--primary, blue) */</code></pre></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>✨ CSS Animations &amp; Transitions</h2><pre data-v-25cae97f><code data-v-25cae97f>.btn {
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s;
}
.btn:hover { transform: translateY(-3px) scale(1.02); box-shadow: 0 8px 24px rgba(0,0,0,0.15); }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
.box { animation: fadeIn 0.5s ease forwards; }</code></pre></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>🧱 BEM Methodology</h2><pre data-v-25cae97f><code data-v-25cae97f>/* Block__Element--Modifier */
.card { }                    /* Block */
.card__title { }             /* Element */
.card__title--highlight { }  /* Modifier */
.card--featured { }          /* Modifier của Block */</code></pre></div><div class="section" data-v-25cae97f><h2 data-v-25cae97f>🎪 25+ CSS Techniques</h2><div class="grid-2" data-v-25cae97f><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Hover Effect</h4><p data-v-25cae97f><code data-v-25cae97f>cubic-bezier</code> spring + glow shadow</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Tooltip</h4><p data-v-25cae97f><code data-v-25cae97f>[data-tooltip]::after</code> CSS-only</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Glassmorphism</h4><p data-v-25cae97f><code data-v-25cae97f>backdrop-filter: blur(14px)</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Neumorphism</h4><p data-v-25cae97f>Inset/outset soft shadows</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Card Hover</h4><p data-v-25cae97f>Sweep shimmer <code data-v-25cae97f>::before</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Ripple Effect</h4><p data-v-25cae97f>JS + <code data-v-25cae97f>@keyframes</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Skeleton</h4><p data-v-25cae97f>Shimmer gradient animation</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Gradient Text</h4><p data-v-25cae97f><code data-v-25cae97f>background-clip: text</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Flip Card</h4><p data-v-25cae97f><code data-v-25cae97f>perspective + rotateY</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Accordion</h4><p data-v-25cae97f>Checkbox hack CSS-only</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Modal</h4><p data-v-25cae97f><code data-v-25cae97f>:target</code> pseudo-class</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Toggle Switch</h4><p data-v-25cae97f>Checkbox styling + spring</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Custom Scrollbar</h4><p data-v-25cae97f><code data-v-25cae97f>::-webkit-scrollbar</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Masonry</h4><p data-v-25cae97f><code data-v-25cae97f>columns: 3</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Parallax</h4><p data-v-25cae97f><code data-v-25cae97f>background-attachment</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Loading Spinner</h4><p data-v-25cae97f>Border rotation keyframe</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Timeline</h4><p data-v-25cae97f><code data-v-25cae97f>::before</code> line + dots</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Animated Button</h4><p data-v-25cae97f>Slide fill <code data-v-25cae97f>::before</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Sticky Header</h4><p data-v-25cae97f><code data-v-25cae97f>position: sticky</code></p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Dropdown</h4><p data-v-25cae97f>CSS hover menu</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Sidebar</h4><p data-v-25cae97f>Checkbox toggle animation</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Responsive Nav</h4><p data-v-25cae97f>Media query + hamburger</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Image Zoom</h4><p data-v-25cae97f><code data-v-25cae97f>scale(1.25)</code> overflow hidden</p></div><div class="card" data-v-25cae97f><h4 data-v-25cae97f>Carousel</h4><p data-v-25cae97f>JS + CSS <code data-v-25cae97f>translateX</code></p></div></div></div>`,9)])])}var p=r(s,[[`render`,f],[`__scopeId`,`data-v-25cae97f`]]);export{p as default};